//! OST's text in the app language: one translator for the desktop's QML
//! (its QTranslator asks this one), the desktop's Rust and the engine.
//!
//! Every string OST shows is written in English in the code (`tr("…")` in
//! Rust, `qsTr("…")` in QML) and keyed to the Teams string id whose en-us
//! text it is (desktop/i18n/ids.json, generated by desktop/i18n/l10n.py).
//! The catalogue of Teams' own translations, built on the device from
//! Teams' string resources (api::teams_strings), maps each id to its text
//! in Qt's form: `%1`, `%2`… for Teams' placeholders in their en-us order,
//! `%n` for a count, and a plural message as its forms
//! (`{"=1": …, "one": …, "other": …}`), picked as Teams' ICU messages pick
//! them: an exact `=N` form first, else the language's CLDR category.
//!
//! Until [`install`] runs (the TUI, tests, an app language whose strings
//! couldn't be had) every string reads as its English, plural forms
//! included.

use std::collections::HashMap;
use std::sync::{Arc, RwLock};

use serde_json::Value;

struct Catalogue {
    index: HashMap<String, usize>,
    rows: Vec<Value>,
    /// The plural-rule language ("de", "pt-br").
    lang: String,
    /// The digits a count is written in (Teams formats `#` in its
    /// language's own numbering system: Arabic-Indic for ar, Persian for fa).
    zero: char,
    /// A translated text back to OST's English (for reports to GitHub).
    english: HashMap<String, String>,
}

static CATALOGUE: RwLock<Option<Arc<Catalogue>>> = RwLock::new(None);

fn key(source: &str, dis: &str) -> String {
    if dis.is_empty() {
        source.to_string()
    } else {
        format!("{source}\u{4}{dis}")
    }
}

/// OST's strings keyed to Teams' ids (desktop/i18n/ids.json).
pub const IDS: &str = include_str!("../desktop/i18n/ids.json");

/// Install OST's strings in `locale` (one of Teams' string locales,
/// "de-de"): `catalogue` is the built catalogue's JSON (`{"strings": {id:
/// …}}`), none for en-us (OST's own English plural forms then).
pub fn install(catalogue: Option<&str>, locale: &str) -> anyhow::Result<()> {
    let cat = Catalogue::new(IDS, catalogue, locale)?;
    *CATALOGUE.write().unwrap() = Some(Arc::new(cat));
    *LOCALE.write().unwrap() = if catalogue.is_some() {
        locale.to_string()
    } else {
        String::new()
    };
    Ok(())
}

static LOCALE: RwLock<String> = RwLock::new(String::new());

/// The app language's string locale ("de-de") while a translated catalogue
/// is in use; empty in English. Services that word text for Teams (meeting
/// options' `translations`) are asked in it, as Teams' Accept-Language.
pub fn locale() -> String {
    LOCALE.read().unwrap().clone()
}

/// `items` as one list in `locale`'s words, as Teams'
/// `new Intl.ListFormat(locale).format(items)` (a conjunction, long style;
/// CLDR's list patterns): "A and B", "A, B, and C" in en-us, "A und B",
/// "A, B und C" in de-de, "A、B、C" in ja-jp. An empty locale is en-us, as
/// [`locale`] is in English.
pub fn list_and(items: &[String], locale: &str) -> String {
    use icu_list::{ListFormatter, options::ListFormatterOptions};
    let tag = if locale.is_empty() { "en-us" } else { locale };
    let loc = icu_locale_core::Locale::try_from_str(tag)
        .unwrap_or_else(|_| icu_locale_core::Locale::try_from_str("en-us").expect("en-us"));
    match ListFormatter::try_new_and((&loc).into(), ListFormatterOptions::default()) {
        // Newer CLDR joins Hebrew's "ו" with a non-breaking hyphen; Teams'
        // engine (WebView2) still writes "ו-C".
        Ok(f) => f.format_to_string(items.iter()).replace('\u{2011}', "-"),
        Err(_) => items.join(", "),
    }
}

impl Catalogue {
    fn new(ids: &str, catalogue: Option<&str>, locale: &str) -> anyhow::Result<Self> {
        let strings = match catalogue {
            Some(c) => {
                let v: Value = serde_json::from_str(c)?;
                match v.get("strings") {
                    Some(Value::Object(m)) if !m.is_empty() => m.clone(),
                    _ => anyhow::bail!("catalogue has no strings"),
                }
            }
            None => serde_json::Map::new(),
        };
        let rows_in: Vec<Vec<Value>> = serde_json::from_str(ids)?;
        let mut index = HashMap::with_capacity(rows_in.len() * 2);
        let mut rows = Vec::with_capacity(rows_in.len());
        let mut english = HashMap::new();
        for (i, r) in rows_in.iter().enumerate() {
            let s = |k: usize| r.get(k).and_then(Value::as_str).unwrap_or_default();
            let (source, dis, id) = (s(0), s(1), s(2));
            // Teams' translation, else OST's English plural forms.
            rows.push(
                strings
                    .get(id)
                    .cloned()
                    .or_else(|| r.get(4).cloned())
                    .unwrap_or(Value::Null),
            );
            index.insert(key(source, dis), i);
            // the id names the string too: tr_id("…", "<ns>:<key>")
            index.insert(key(source, id), i);
            if let Some(Value::String(t)) = strings.get(id)
                && !source.contains('%')
            {
                english
                    .entry(t.clone())
                    .or_insert_with(|| source.to_string());
            }
        }
        let base = locale.split('-').next().unwrap_or_default();
        let lang = if locale == "pt-br" {
            "pt-br".to_string()
        } else {
            base.to_string()
        };
        let zero = match base {
            "ar" => '\u{660}',
            "fa" => '\u{6f0}',
            _ => '0',
        };
        Ok(Catalogue {
            index,
            rows,
            lang,
            zero,
            english,
        })
    }

    fn row(&self, source: &str, dis: &str) -> Option<&Value> {
        let i = self
            .index
            .get(&key(source, dis))
            .or_else(|| (!dis.is_empty()).then(|| self.index.get(source)).flatten())?;
        self.rows.get(*i)
    }

    /// A plural message's form for `n`: an exact `=N` form first, else the
    /// language's category, else "other"; its `%n` in the language's digits,
    /// `%N` as written.
    fn form(&self, forms: &serde_json::Map<String, Value>, n: i64) -> Option<String> {
        let pick = forms
            .get(&format!("={n}"))
            .or_else(|| forms.get(plural_category(&self.lang, n.unsigned_abs())))
            .or_else(|| forms.get("other"))?;
        Some(
            pick.as_str()?
                .replace("%n", &number_in(n, self.zero))
                .replace("%N", &n.to_string()),
        )
    }

    fn lookup(&self, source: &str, dis: &str, n: Option<i64>) -> Option<String> {
        match self.row(source, dis)? {
            Value::String(s) => Some(match n {
                Some(n) => s
                    .replace("%n", &number_in(n, self.zero))
                    .replace("%N", &n.to_string()),
                None => s.clone(),
            }),
            Value::Object(forms) => self.form(forms, n.unwrap_or(0)),
            _ => None,
        }
    }

    /// A message with several counts (its segments), each count by name.
    fn lookup_counts(&self, source: &str, dis: &str, counts: &[(&str, i64)]) -> Option<String> {
        let Value::Array(segs) = self.row(source, dis)? else {
            return None;
        };
        let mut out = String::new();
        for s in segs {
            match s {
                Value::String(t) => out.push_str(t),
                Value::Object(o) => {
                    let var = o.get("var")?.as_str()?;
                    let n = counts.iter().find(|(k, _)| *k == var)?.1;
                    out.push_str(&self.form(o.get("forms")?.as_object()?, n)?);
                }
                _ => return None,
            }
        }
        Some(out)
    }
}

thread_local! {
    static ENGLISH: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// OST's English (en-us, plural forms included) for what `f` builds on
/// this thread: reports to GitHub stay English whatever the app language,
/// so maintainers can read them.
pub fn in_english<R>(f: impl FnOnce() -> R) -> R {
    struct Reset(bool);
    impl Drop for Reset {
        fn drop(&mut self) {
            ENGLISH.with(|e| e.set(self.0));
        }
    }
    let _reset = Reset(ENGLISH.with(|e| e.replace(true)));
    f()
}

fn english_catalogue() -> Option<Arc<Catalogue>> {
    static EN: std::sync::OnceLock<Option<Arc<Catalogue>>> = std::sync::OnceLock::new();
    EN.get_or_init(|| Catalogue::new(IDS, None, "en-us").ok().map(Arc::new))
        .clone()
}

/// OST's English for a whole text shown in the app language (a window
/// title, a label), for reports; the text itself when it isn't one of
/// OST's translated strings.
pub fn english(text: &str) -> String {
    current()
        .and_then(|c| c.english.get(text).cloned())
        .unwrap_or_else(|| text.to_string())
}

fn current() -> Option<Arc<Catalogue>> {
    if ENGLISH.with(|e| e.get()) {
        return english_catalogue();
    }
    let installed = CATALOGUE.read().unwrap().clone();
    match installed {
        Some(c) => Some(c),
        None => {
            install(None, "en-us").ok()?;
            CATALOGUE.read().unwrap().clone()
        }
    }
}

/// The app language's text for `source` (its disambiguation or Teams id
/// `dis`), `%n` written as `n` when given; None when OST has no such
/// string (it reads as its English).
pub fn lookup(source: &str, dis: &str, n: Option<i64>) -> Option<String> {
    current()?.lookup(source, dis, n)
}

fn number_in(n: i64, zero: char) -> String {
    let s = n.to_string();
    if zero == '0' {
        return s;
    }
    s.chars()
        .map(|c| {
            c.to_digit(10)
                .and_then(|d| char::from_u32(zero as u32 + d))
                .unwrap_or(c)
        })
        .collect()
}

/// A count in the app language's digits ("11", "١١" in Arabic).
pub fn number(n: i64) -> String {
    let zero = current().map_or('0', |c| c.zero);
    number_in(n, zero)
}

/// `source` in the app language: Teams' wording where OST has the string,
/// else the English.
pub fn tr(source: &str) -> String {
    lookup(source, "", None).unwrap_or_else(|| source.to_string())
}

/// `tr` for a count: `%n` is the number, and the plural form the
/// language's for it.
pub fn tr_n(source: &str, n: i64) -> String {
    lookup(source, "", Some(n)).unwrap_or_else(|| source.replace("%n", &n.to_string()))
}

/// `tr` naming the Teams string explicitly (`"<namespace>:<key>"`), where
/// Teams has several strings with the same English.
pub fn tr_id(source: &str, id: &str) -> String {
    lookup(source, id, None).unwrap_or_else(|| source.to_string())
}

/// `tr_n` naming the Teams string explicitly.
pub fn tr_id_n(source: &str, id: &str, n: i64) -> String {
    lookup(source, id, Some(n)).unwrap_or_else(|| source.replace("%n", &n.to_string()))
}

/// A Teams message with several counts (`{hour, plural, …} {min, plural,
/// …}`), named by its id, each count by Teams' name for it; `source` is
/// only OST's label for it (the English comes from ids.json).
pub fn tr_id_counts(source: &str, id: &str, counts: &[(&str, i64)]) -> String {
    current()
        .and_then(|c| c.lookup_counts(source, id, counts))
        .unwrap_or_else(|| {
            counts
                .iter()
                .map(|(k, n)| format!("{n} {k}"))
                .collect::<Vec<_>>()
                .join(" ")
        })
}

/// A translated text's placeholders `%1`…`%9` filled with `args`, in one
/// pass (an argument holding "%2" stays as it is).
pub fn fill(text: &str, args: &[&str]) -> String {
    let mut out = String::with_capacity(text.len() + args.iter().map(|a| a.len()).sum::<usize>());
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '%'
            && let Some(d) = chars.peek().and_then(|d| d.to_digit(10))
            && d >= 1
            && let Some(a) = args.get(d as usize - 1)
        {
            chars.next();
            out.push_str(a);
            continue;
        }
        out.push(c);
    }
    out
}

/// CLDR's cardinal plural category of a whole number in Teams' string
/// languages (what Teams' ICU messages pick a form by).
pub fn plural_category(lang: &str, n: u64) -> &'static str {
    let (m10, m100) = (n % 10, n % 100);
    let within = |v: u64, a: u64, b: u64| v >= a && v <= b;
    match lang {
        "ar" => match n {
            0 => "zero",
            1 => "one",
            2 => "two",
            _ if within(m100, 3, 10) => "few",
            _ if within(m100, 11, 99) => "many",
            _ => "other",
        },
        "cy" => match n {
            0 => "zero",
            1 => "one",
            2 => "two",
            3 => "few",
            6 => "many",
            _ => "other",
        },
        "he" => match n {
            1 => "one",
            2 => "two",
            _ => "other",
        },
        "ru" | "uk" => {
            if m10 == 1 && m100 != 11 {
                "one"
            } else if within(m10, 2, 4) && !within(m100, 12, 14) {
                "few"
            } else {
                "many"
            }
        }
        "bs" | "hr" | "sr" => {
            if m10 == 1 && m100 != 11 {
                "one"
            } else if within(m10, 2, 4) && !within(m100, 12, 14) {
                "few"
            } else {
                "other"
            }
        }
        "pl" => {
            if n == 1 {
                "one"
            } else if within(m10, 2, 4) && !within(m100, 12, 14) {
                "few"
            } else {
                "many"
            }
        }
        "cs" | "sk" => match n {
            1 => "one",
            2..=4 => "few",
            _ => "other",
        },
        "lt" => {
            if m10 == 1 && !within(m100, 11, 19) {
                "one"
            } else if within(m10, 2, 9) && !within(m100, 11, 19) {
                "few"
            } else {
                "other"
            }
        }
        "lv" => {
            if m10 == 0 || within(m100, 11, 19) {
                "zero"
            } else if m10 == 1 && m100 != 11 {
                "one"
            } else {
                "other"
            }
        }
        "ro" => {
            if n == 1 {
                "one"
            } else if n == 0 || within(m100, 2, 19) {
                "few"
            } else {
                "other"
            }
        }
        "sl" => match m100 {
            1 => "one",
            2 => "two",
            3 | 4 => "few",
            _ => "other",
        },
        "mt" => {
            if n == 1 {
                "one"
            } else if n == 2 {
                "two"
            } else if n == 0 || within(m100, 3, 10) {
                "few"
            } else if within(m100, 11, 19) {
                "many"
            } else {
                "other"
            }
        }
        "mk" | "is" => {
            if m10 == 1 && m100 != 11 {
                "one"
            } else {
                "other"
            }
        }
        "fr" | "pt-br" => {
            if n == 0 || n == 1 {
                "one"
            } else if n.is_multiple_of(1_000_000) {
                "many"
            } else {
                "other"
            }
        }
        "es" | "it" | "ca" | "pt" => {
            if n == 1 {
                "one"
            } else if n != 0 && n.is_multiple_of(1_000_000) {
                "many"
            } else {
                "other"
            }
        }
        "hi" | "fa" => {
            if n <= 1 {
                "one"
            } else {
                "other"
            }
        }
        "fil" => {
            if within(n, 1, 3) || !matches!(m10, 4 | 6 | 9) {
                "one"
            } else {
                "other"
            }
        }
        "ja" | "ko" | "zh" | "th" | "vi" | "id" | "ms" | "lo" | "km" => "other",
        _ => {
            if n == 1 {
                "one"
            } else {
                "other"
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const TEST_IDS: &str = r#"[["Call ended","","calling:ka",[]],["%1 added %2 to the chat.","messaging:kb","messaging:kb",["<0>","<1>"]],["%n others","","messaging:kc_mf",[],{"one":"%n other","other":"%n others"}],["%1 added %2 to the chat.","","messaging:kd",["initiator","targetOne"]]]"#;

    #[test]
    fn teams_wording_with_english_fallback() {
        let en = Catalogue::new(TEST_IDS, None, "en-us").unwrap();
        let t = |c: &Catalogue, s: &str, d: &str, n: Option<i64>| c.lookup(s, d, n);
        assert_eq!(t(&en, "Call ended", "", None), None);
        // OST's English plural forms need no catalogue
        assert_eq!(t(&en, "%n others", "", Some(1)).unwrap(), "1 other");
        assert_eq!(t(&en, "%n others", "", Some(3)).unwrap(), "3 others");
        let cat = r#"{"strings":{"calling:ka":"Anruf beendet","messaging:kb":"%1 hat %2 zum Chat hinzugefügt.","messaging:kc_mf":{"one":"%n weitere Person","other":"%n weitere Personen"}}}"#;
        let de = Catalogue::new(TEST_IDS, Some(cat), "de-de").unwrap();
        assert_eq!(t(&de, "Call ended", "", None).unwrap(), "Anruf beendet");
        assert_eq!(
            fill(
                &t(&de, "%1 added %2 to the chat.", "messaging:kb", None).unwrap(),
                &["Ann", "Bo %1"]
            ),
            "Ann hat Bo %1 zum Chat hinzugefügt."
        );
        // the same English under another id Teams hasn't translated: English
        assert_eq!(t(&de, "%1 added %2 to the chat.", "", None), None);
        assert_eq!(
            t(&de, "%n others", "", Some(1)).unwrap(),
            "1 weitere Person"
        );
        assert_eq!(
            t(&de, "%n others", "", Some(4)).unwrap(),
            "4 weitere Personen"
        );
        assert_eq!(t(&de, "Not OST's", "", None), None);
        let cat = r#"{"strings":{"messaging:kc_mf":{"one":"%n آخر","two":"اثنان آخران","few":"%n آخرين","other":"%n آخر"}}}"#;
        let ar = Catalogue::new(TEST_IDS, Some(cat), "ar-sa").unwrap();
        assert_eq!(t(&ar, "%n others", "", Some(2)).unwrap(), "اثنان آخران");
        assert_eq!(t(&ar, "%n others", "", Some(11)).unwrap(), "١١ آخر");
        assert_eq!(t(&ar, "%n others", "", Some(5)).unwrap(), "٥ آخرين");
        assert_eq!(number_in(2026, ar.zero), "٢٠٢٦");
        assert!(Catalogue::new(TEST_IDS, Some(r#"{"strings":{}}"#), "de-de").is_err());
    }

    #[test]
    fn several_counts_and_raw_counts() {
        let ids = r#"[["{hour}h {min}m {sec}s","messaging:kd_mf","messaging:kd_mf",[],[{"var":"hour","forms":{"=0":"","other":"%nh"}}," ",{"var":"min","forms":{"=0":"","other":"%nm"}}," ",{"var":"sec","forms":{"=0":"","other":"%ns"}}]],["and will expire in %n days.","messaging:ke_mf","messaging:ke_mf",[],{"=1":"and will expire in %N day.","other":"and will expire in %N days."}]]"#;
        let en = Catalogue::new(ids, None, "en-us").unwrap();
        let c = |cat: &Catalogue, h, m, s| {
            cat.lookup_counts(
                "{hour}h {min}m {sec}s",
                "messaging:kd_mf",
                &[("hour", h), ("min", m), ("sec", s)],
            )
            .unwrap()
            .trim()
            .to_string()
        };
        assert_eq!(c(&en, 0, 11, 0), "11m");
        assert_eq!(c(&en, 1, 0, 5), "1h  5s");
        let cat = r#"{"strings":{"messaging:kd_mf":[{"var":"hour","forms":{"=0":"","other":"%nس"}}," ",{"var":"min","forms":{"=0":"","other":"%nد"}}," ",{"var":"sec","forms":{"=0":"","other":"%nث"}}],"messaging:ke_mf":{"other":"في غضون %N يوماً."}}}"#;
        let ar = Catalogue::new(ids, Some(cat), "ar-sa").unwrap();
        // Teams: "٥د ٥٤ث" (#), but "في غضون 120 يوماً" ({remainingDays})
        assert_eq!(c(&ar, 0, 5, 54), "٥د ٥٤ث");
        assert_eq!(
            ar.lookup("and will expire in %n days.", "messaging:ke_mf", Some(120))
                .unwrap(),
            "في غضون 120 يوماً."
        );
    }

    #[test]
    fn reports_in_english() {
        let cat = r#"{"strings":{"calling:ka":"Anruf beendet"}}"#;
        let de = Catalogue::new(TEST_IDS, Some(cat), "de-de").unwrap();
        assert_eq!(
            de.english.get("Anruf beendet").map(String::as_str),
            Some("Call ended")
        );
        // in_english: OST's English on this thread, whatever is installed
        assert_eq!(
            in_english(|| tr_id_n("%n others", "messaging:k7xsi91tl_mf", 1)),
            "1 other"
        );
        assert_eq!(english("not translated"), "not translated");
    }

    #[test]
    fn english_by_default() {
        // nothing installed in tests: OST's English, plural forms included
        assert_eq!(tr("Call ended"), "Call ended");
        assert_eq!(tr_id_n("%n others", "messaging:k7xsi91tl_mf", 1), "1 other");
        assert_eq!(
            tr_id_n("%n others", "messaging:k7xsi91tl_mf", 2),
            "2 others"
        );
    }

    #[test]
    fn plural_categories() {
        assert_eq!(plural_category("ar", 0), "zero");
        assert_eq!(plural_category("ar", 103), "few");
        assert_eq!(plural_category("ar", 111), "many");
        assert_eq!(plural_category("ru", 21), "one");
        assert_eq!(plural_category("ru", 12), "many");
        assert_eq!(plural_category("pl", 22), "few");
        assert_eq!(plural_category("fr", 0), "one");
        assert_eq!(plural_category("de", 0), "other");
        assert_eq!(plural_category("ja", 1), "other");
    }

    #[test]
    fn fill_is_one_pass() {
        assert_eq!(fill("%2 vor %1", &["a", "b"]), "b vor a");
        assert_eq!(fill("100% %1", &["x"]), "100% x");
        assert_eq!(fill("%3", &["x"]), "%3");
    }
}
